use crate::Project;
use serde::{Serialize,Deserialize};
use std::collections::{HashMap,HashSet};
use uuid::Uuid;
#[derive(Clone,Copy,Debug,Default,PartialEq,Eq,Serialize,Deserialize)]
pub enum Body { #[default] None, Static, Dynamic, Trigger }
#[derive(Clone,Debug,PartialEq,Serialize,Deserialize)]
pub struct Animation { pub columns:u32,pub rows:u32,pub frames:u32,pub fps:f32,#[serde(default = "default_looping")] pub looping:bool, #[serde(default)] pub start:u32, #[serde(default)] pub durations:Vec<u32>, #[serde(default)] pub regions:Vec<[f32;4]>, #[serde(default, skip_serializing_if = "std::collections::BTreeMap::is_empty")] pub frame_geometry:std::collections::BTreeMap<u32,[f32;4]> }
fn default_looping()->bool{true}
impl Default for Animation {fn default()->Self{Self{columns:1,rows:1,frames:1,fps:8.,looping:true,start:0,durations:vec![],regions:vec![],frame_geometry:Default::default()}}}
impl Animation {pub fn total_frames(&self)->u32 {if self.regions.is_empty(){self.columns.max(1).saturating_mul(self.rows.max(1))}else{self.regions.len().min(16384) as u32}} pub fn frame(&self,t:f32)->u32{let total=self.total_frames();let start=self.start.min(total-1);let n=self.frames.max(1).min(total-start);if self.durations.len()==n as usize && self.durations.iter().all(|&d|d>0){let total:u64=self.durations.iter().map(|&d|u64::from(d)).sum();let mut ms=(t.max(0.)*1000.) as u64;ms=if self.looping{ms%total}else{ms.min(total-1)};for (i,&d) in self.durations.iter().enumerate(){if ms<u64::from(d){return start+i as u32;}ms-=u64::from(d);}}let f=(t*self.fps.max(0.)) as u32;start+if self.looping{f%n}else{f.min(n-1)}} pub fn uv(&self,t:f32)->[[f32;2];4]{let c=self.columns.max(1);let r=self.rows.max(1);let f=self.frame(t);if let Some(&[x,y,w,h])=self.regions.get(f as usize){if crate::valid_region([x,y,w,h]){return [[x,y],[x+w,y],[x+w,y+h],[x,y+h]];}}let x=(f%c) as f32/c as f32;let y=(f/c) as f32/r as f32;let w=1./c as f32;let h=1./r as f32;[[x,y],[x+w,y],[x+w,y+h],[x,y+h]]}}
#[derive(Clone,Copy,Debug,PartialEq,Eq,Serialize,Deserialize)]
pub enum NodeKind { SetVariable, AddVariable, MultiplyVariable, IfPositive, Update, Trigger, MoveRight, MoveUp, Jump, MoveLeft, MoveDown, IfRight, IfJump }
#[derive(Clone,Debug,Default,PartialEq,Serialize,Deserialize)]
pub struct Graph {pub nodes:Vec<NodeKind>,pub edges:Vec<[usize;2]>, #[serde(default)] pub params:std::collections::BTreeMap<usize,crate::NodeParam>}
impl Graph {pub fn actions(&self,event:NodeKind)->Vec<NodeKind>{self.actions_input(event,[0.,0.])} pub fn actions_input(&self,event:NodeKind,input:[f32;2])->Vec<NodeKind>{let mut queue:Vec<usize>=self.nodes.iter().enumerate().filter_map(|(i,n)|(*n==event).then_some(i)).collect();let mut seen=HashSet::new();let mut out=vec![];while let Some(i)=queue.pop(){if !seen.insert(i){continue}if let Some(n)=self.nodes.get(i){if (*n==NodeKind::IfRight && input[0]<=0.)||(*n==NodeKind::IfJump && input[1]<=0.){continue;}out.push(*n);for e in &self.edges{if e[0]==i{queue.push(e[1]);}}}}out}}
#[derive(Default)]
pub struct Simulation { rapier: crate::RapierWorld,pub elapsed:f32, velocity:HashMap<Uuid,f32>, touching:HashSet<(Uuid,Uuid)>, #[cfg(feature="lua")] lua:HashMap<Uuid,(String,mlua::Lua)>, pub errors:Vec<String>,pub events:Vec<String>}
fn overlap(a:&crate::Object,b:&crate::Object)->bool{(0..2).all(|i|(a.position[i]-b.position[i]).abs()<(a.size[i]+b.size[i])*0.5)}
impl Simulation {
 pub fn step(&mut self,p:&mut Project,dt:f32,input:[f32;2]){let dt=dt.clamp(0.,0.033);self.elapsed+=dt;crate::combat::advance(p,dt);let before=p.clone();let solids=p.objects.iter().filter(|o|o.body==Body::Static).cloned().collect::<Vec<_>>();let mut solid_index=crate::spatial::SpatialIndex::default();for (i,b) in solids.iter().enumerate(){solid_index.insert(i,b.position,b.size.map(|v|v*0.5),128.);}
 let triggers=p.objects.iter().filter(|o|o.body==Body::Trigger).cloned().collect::<Vec<_>>();let mut contacts=HashSet::new();#[cfg(feature="lua")] let mut spawned:Vec<crate::Object>=Vec::new();#[cfg(not(feature="lua"))] let spawned:Vec<crate::Object>=Vec::new();let mut jumps=Vec::new();for o in &mut p.objects{if o.camera||o.pro.combat.as_ref().is_some_and(|c|c.health<=0.)||matches!(o.body,Body::Static|Body::Trigger){continue}let old=o.position;crate::navigate(o,&before,dt);if !o.motion.transitions.is_empty(){crate::transition_clip(o,if o.player{input}else{[0.;2]},self.elapsed);}else if o.motion.auto_state && o.player {let name=if input[1]>0. {"Jump"}else if input[0].abs()>0.01 || input[1].abs()>0.01 {"Run"}else{"Idle"};if o.clip_name!=name {if let Some(clip)=o.clips.get(name){o.animation=clip.clone();o.clip_name=name.into();o.pro.variables.insert("forge_clip_started".into(),self.elapsed);}}}if o.body==Body::None && !o.player {if let Some((pos,rot))=o.motion.sample_clip(&o.clip_name,crate::animation_time(o,self.elapsed),self.elapsed,&o.animation){o.position=pos;o.rotation=rot;}}let v=self.velocity.entry(o.id).or_default();let old_v=*v;if o.player && !(p.settings.rapier && o.body==Body::Dynamic) {o.position[0]+=input[0]*o.material.speed*dt;if o.body!=Body::Dynamic{o.position[1]+=input[1]*o.material.speed*dt;}else if input[1]>0. && v.abs()<0.01{*v=o.material.jump_speed;}}for n in o.graph.execute(NodeKind::Update,input,&mut o.pro.variables){match n{NodeKind::MoveRight=>o.position[0]+=100.*dt,NodeKind::MoveUp=>o.position[1]+=100.*dt,NodeKind::MoveLeft=>o.position[0]-=100.*dt,NodeKind::MoveDown=>o.position[1]-=100.*dt,NodeKind::Jump=>if v.abs()<0.01{*v=o.material.jump_speed},_=>{}}}
 #[cfg(feature="lua")] if !o.script.trim().is_empty(){let entry=self.lua.entry(o.id).or_insert_with(||(String::new(),mlua::Lua::new()));if entry.0!=o.script{entry.0=o.script.clone();entry.1=mlua::Lua::new();let lua=&entry.1;let _=lua.set_hook(mlua::HookTriggers::new().every_nth_instruction(10000),|_,_| Err(mlua::Error::RuntimeError("Instruction budget exceeded".into())));if let Err(e)=lua.load(&o.script).exec(){self.errors.push(e.to_string());}}let lua=&entry.1;let g=lua.globals();let _=g.set("x",o.position[0]);let _=g.set("y",o.position[1]);let _=g.set("input_x",input[0]);let _=g.set("input_y",input[1]);let _=g.set("elapsed",self.elapsed);let _=g.set("velocity_y",*v);let _=g.set("object_name",o.name.clone());let _=g.set("jump_speed",o.material.jump_speed);let _=g.set("clip_name",o.clip_name.clone());let names=lua.create_table();if let Ok(names)=names{for obj in &before.objects{let _=names.set(obj.name.clone(),obj.id.to_string());}let _=g.set("objects",names);}let _=g.set("spawn_queue",lua.create_table().unwrap());let _=g.set("event_queue",lua.create_table().unwrap());let _=lua.load("function move(dx,dy) x=x+dx; y=y+dy end; function jump() velocity_y=jump_speed end; function get_position() return x,y end; function find_object(name) return objects[name] end; function play_animation(name) clip_name=name end; function spawn(name,px,py) table.insert(spawn_queue,{name,px,py}) end; function emit(name) table.insert(event_queue,name) end; timers=timers or {}; function timer(name,seconds) if timers[name]==nil then timers[name]=elapsed+seconds end; if elapsed>=timers[name] then timers[name]=nil; return true end; return false end").exec();if let Ok(f)=g.get::<mlua::Function>("update"){match f.call::<()>(dt){Ok(())=>{if let (Ok(x),Ok(y))=(g.get::<f32>("x"),g.get::<f32>("y")){if x.is_finite()&&y.is_finite(){o.position=[x,y];if let Ok(vy)=g.get::<f32>("velocity_y"){if vy.is_finite(){*v=vy.clamp(-10000.,10000.);}}}}},Err(e)=>self.errors.push(e.to_string())}}}
 #[cfg(feature="lua")] if let Some((_,lua))=self.lua.get(&o.id){let g=lua.globals();if let Ok(name)=g.get::<String>("clip_name"){if name!=o.clip_name{if let Some(c)=o.clips.get(&name){o.animation=c.clone();o.clip_name=name;o.pro.variables.insert("forge_clip_started".into(),self.elapsed);}}}if let Ok(q)=g.get::<mlua::Table>("spawn_queue"){for row in q.sequence_values::<mlua::Table>().take(32).flatten(){if let (Ok(name),Ok(x),Ok(y))=(row.get::<String>(1),row.get::<f32>(2),row.get::<f32>(3)){if x.is_finite()&&y.is_finite()&&spawned.len()<128{spawned.push(crate::Object::new(&name,[x,y],[32.,32.],[255;4]));}}}}if let Ok(q)=g.get::<mlua::Table>("event_queue"){for event in q.sequence_values::<String>().take(32).flatten(){self.events.push(event);}}let _=g.set("spawn_queue",lua.create_table().unwrap());let _=g.set("event_queue",lua.create_table().unwrap());}if p.settings.rapier && o.body==Body::Dynamic && *v!=old_v{jumps.push((o.id,*v));*v=0.;}if o.body==Body::Dynamic && !p.settings.rapier{let target_y=o.position[1];o.position[1]=old[1];let candidates=solid_index.query(o.position,o.size.map(|v|v*0.5),128.);if candidates.as_ref().map_or(true,|ids|ids.iter().any(|&i|overlap(o,&solids[i]))){for b in &solids{if overlap(o,b){o.position[0]=old[0];}}}*v-=720.*o.material.gravity_scale*dt;o.position[1]=target_y+*v*dt;for b in &solids{if overlap(o,b){let half=(o.size[1]+b.size[1])*0.5;o.position[1]=b.position[1]+if *v<=0.{half}else{-half};*v = if v.abs()>40. {-*v*o.material.restitution.clamp(0.,1.)} else {0.};}}}for b in &triggers{if overlap(o,b){let pair=(o.id,b.id);contacts.insert(pair);if !self.touching.contains(&pair){self.events.push(format!("Trigger enter: {} → {}",o.name,b.name));for n in o.graph.execute(NodeKind::Trigger,input,&mut o.pro.variables){match n{NodeKind::MoveRight=>o.position[0]+=32.,NodeKind::MoveUp=>o.position[1]+=32.,NodeKind::MoveLeft=>o.position[0]-=32.,NodeKind::MoveDown=>o.position[1]-=32.,NodeKind::Jump=>*v=o.material.jump_speed,_=>{}}}#[cfg(feature="lua")] if let Some((_,lua))=self.lua.get(&o.id){if let Ok(f)=lua.globals().get::<mlua::Function>("on_trigger"){if let Err(e)=f.call::<()>(b.name.clone()){self.errors.push(e.to_string());}}}}}}}if dt>0.&&p.objects.iter().any(|o|!o.motion.events.is_empty()){let old:HashMap<_,_>=before.objects.iter().map(|o|(o.id,o)).collect();for o in &p.objects{if o.motion.events.is_empty(){continue;}let now=crate::animation_time(o,self.elapsed);let prev=old.get(&o.id).map(|v|crate::animation_time(v,(self.elapsed-dt).max(0.))).unwrap_or(0.);let restart=self.elapsed<=dt||old.get(&o.id).is_none_or(|v|v.clip_name!=o.clip_name)||now<prev;for event in crate::crossed_events(o,prev,now,restart){self.events.push(format!("Animation {}: {}",o.name,event));#[cfg(feature="lua")] if let Some((_,lua))=self.lua.get(&o.id){if let Ok(f)=lua.globals().get::<mlua::Function>("on_animation_event"){if let Err(e)=f.call::<()>(event.clone()){self.errors.push(e.to_string());}}}}}}if p.objects.len()+spawned.len()<=10000{p.objects.extend(spawned);}if p.settings.rapier{self.rapier.step(p,dt,input,&jumps);}crate::inherit_world(&before,p);self.touching=contacts;if self.events.len()>100{self.events.drain(..self.events.len()-100);}if self.errors.len()>100{self.errors.drain(..self.errors.len()-100);}}
}
pub fn project_point(p:[f32;2],iso:bool)->[f32;2]{if iso{[(p[0]-p[1])*0.866,(p[0]+p[1])*0.5]}else{p}}
pub fn unproject_point(p:[f32;2],iso:bool)->[f32;2]{if iso{[p[1]+p[0]/1.732,p[1]-p[0]/1.732]}else{p}}
#[cfg(test)] mod tests{use super::*;#[test]fn atlas(){let a=Animation{columns:4,rows:2,frames:8,fps:4.,looping:true,start:0,durations:vec![],regions:vec![],frame_geometry:Default::default()};assert_eq!(a.frame(2.),0);assert_eq!(a.frame(1.25),5);}#[test]fn graph_cycle(){let g=Graph{nodes:vec![NodeKind::Update,NodeKind::MoveRight],edges:vec![[0,1],[1,0]],..Default::default()};assert_eq!(g.actions(NodeKind::Update).len(),2);}#[test]fn projection(){let p=unproject_point(project_point([32.,64.],true),true);assert!((p[0]-32.).abs()<0.001);}}
